// scripts/sign-rulesets.mjs
//
// Signs the built-in rule set definitions (packages/core/src/
// builtin-definitions.ts) and emits packages/core/src/
// builtin-rulesets.generated.ts, which is what ships.
//
// Requires a prior core build: this script imports the COMPILED core
// (packages/core/dist), because TypeScript sources use NodeNext ".js"
// specifiers that node's type-stripping does not remap to ".ts".
// Run `npm run build -w @tamtunnel/agentarb-core` first. On a fresh
// checkout the generated file does not exist yet, so bootstrap with a
// placeholder (empty BUILTIN_RULESETS) for the first build, then run
// this script to replace it with the signed sets, then rebuild.
//
// The signing key: if AGENTARB_RULESET_SIGNING_KEY is set (a JSON-encoded
// Ed25519 private JWK), it is used. Otherwise a fresh keypair is generated
// and its private JWK is printed to stderr ONCE — save it if you ever need
// to re-sign these exact rule sets; the public DID is embedded in the
// generated file, so re-signing with a different key also requires
// updating BUILTIN_SIGNER_DID there.
//
// The private key is never written to the repo. A built-in rule set whose
// signature does not verify against the embedded DID refuses to load
// (see loadBuiltinRulesets in packages/core/src/rulesets.ts).

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { BUILTIN_RULESET_DEFS } from "../packages/core/dist/builtin-definitions.js";
import { signRuleset } from "../packages/core/dist/rulesets.js";
import {
  generateKeypair,
  didFromPrivateJwk,
} from "../packages/core/dist/jws.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const outPath = path.join(
  here,
  "..",
  "packages",
  "core",
  "src",
  "builtin-rulesets.generated.ts",
);

let privateJwk;
let generated = false;
if (process.env.AGENTARB_RULESET_SIGNING_KEY) {
  privateJwk = JSON.parse(process.env.AGENTARB_RULESET_SIGNING_KEY);
} else {
  const kp = generateKeypair();
  privateJwk = kp.privateJwk;
  generated = true;
}
const signerDid = didFromPrivateJwk(privateJwk);

const signed = BUILTIN_RULESET_DEFS.map((rs) => signRuleset(rs, privateJwk));

const header = `// packages/core/src/builtin-rulesets.generated.ts
//
// GENERATED by scripts/sign-rulesets.mjs — do not edit by hand.
// Re-generate after changing builtin-definitions.ts. The built-in signer
// DID below is the trust root for built-in rule sets: loadBuiltinRulesets()
// refuses any set whose signature does not verify against it.

import type { SignedRuleset } from "./rulesets.js";

export const BUILTIN_SIGNER_DID = ${JSON.stringify(signerDid)};

export const BUILTIN_RULESETS: SignedRuleset[] = ${JSON.stringify(signed, null, 2)};
`;

fs.writeFileSync(outPath, header);
console.log(`wrote ${outPath}`);
console.log(`built-in signer: ${signerDid}`);
if (generated) {
  console.error(
    "NOTE: fresh signing key generated (not saved to the repo). " +
      "Private JWK (save it if you need to re-sign these rule sets):",
  );
  console.error(JSON.stringify(privateJwk));
}
